mapper.select:
SELECT v.id, v.name, v.code, v.type, v.capacity, v.price, v.open_time, v.close_time, v.open_time_desc, v.description, v.status, v.cover_image_url, v.image_urls, v.remark, v.create_time, v.update_time, fp.id AS floor_plan_id, fp.title AS floor_plan_title, i.item_uid AS floor_plan_item_uid, i.label AS floor_plan_item_label FROM venue v LEFT JOIN floor_plan_item i ON i.venue_id = v.id LEFT JOIN floor_plan_item_rel r ON r.floor_plan_item_id = i.id LEFT JOIN floor_plan fp ON fp.id = r.floor_plan_id AND fp.is_deleted = 0
AND v.type LIKE CONCAT('%', #{type}, '%')
AND v.status = #{status}
AND (v.name LIKE CONCAT('%', #{keyword}, '%') OR v.code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY v.create_time DESC LIMIT #{offset}, #{pageSize}
